import { Locator, Page, expect } from '@playwright/test';
import BasePage from '../Framework/src/pages/base.page';
import { HTMLSubStepLogger } from '../Framework/src/utils/htmlSubStepLogger';

export class StaffPage extends BasePage {
  constructor(page: Page, subStepLogger?: HTMLSubStepLogger) {
    super(page, subStepLogger);
  }

  // ==================== Locators ====================

  // -- Navigation --
  get staffGuidesNavLink(): Locator {
    return this.page.getByRole('link', { name: 'Staff & Guides' });
  }

  // -- Staff & Guide List (/staff) --
  get pageTitleHeading(): Locator {
    return this.page.getByRole('heading', { name: /staff|guides/i }).first();
  }

  get addGuideButton(): Locator {
    return this.page.getByRole('button', { name: /add guide/i });
  }

  get searchInput(): Locator {
    return this.page.getByPlaceholder(/search by name, email, or phone number/i);
  }

  get ranchFilterDropdown(): Locator {
    return this.page.getByRole('combobox').filter({ hasText: /ranches/i });
  }

  get statusFilterDropdown(): Locator {
    return this.page.getByRole('combobox').filter({ hasText: /status/i });
  }

  get levelFilterDropdown(): Locator {
    return this.page.getByRole('combobox').filter({ hasText: /levels/i });
  }

  get cardViewToggle(): Locator {
    return this.page.getByRole('button', { name: /card view/i });
  }

  get tableViewToggle(): Locator {
    return this.page.getByRole('button', { name: /table view/i });
  }

  get guidesTable(): Locator {
    return this.page.getByRole('table');
  }

  get tableColumnHeaders(): Locator {
    return this.guidesTable.getByRole('columnheader');
  }

  guideRow(nameOrEmail: string): Locator {
    return this.page.getByRole('row', { name: new RegExp(nameOrEmail, 'i') });
  }

  moreOptionsButton(nameOrEmail: string): Locator {
    return this.guideRow(nameOrEmail).getByRole('button', { name: /more options/i });
  }

  get editMenuItem(): Locator {
    return this.page.getByRole('menuitem', { name: /^edit$/i });
  }

  get changeStatusMenuItem(): Locator {
    return this.page.getByRole('menuitem', { name: /change status/i });
  }

  get emptyStateMessage(): Locator {
    return this.page.getByText(/no guides found/i);
  }

  get pageSizeDropdown(): Locator {
    return this.page.getByRole('combobox').filter({ hasText: /^\d+$/ });
  }

  pageNumberButton(pageNumber: string): Locator {
    return this.page.getByRole('button', { name: pageNumber, exact: true });
  }

  get nextPageButton(): Locator {
    return this.page.getByRole('button', { name: /^next$/i });
  }

  get previousPageButton(): Locator {
    return this.page.getByRole('button', { name: /^previous$/i });
  }

  get successToast(): Locator {
    return this.page.locator('[role="status"], [data-sonner-toast], .toast').first();
  }

  fieldValidationError(fieldLabel: string): Locator {
    return this.page
      .locator('div')
      .filter({ has: this.page.getByLabel(new RegExp(fieldLabel, 'i')) })
      .getByText(/required|invalid|must/i)
      .first();
  }

  // -- Add/Edit Guide wizard --

  // Step 1 (Add only) — Ranch assignment
  get ranchSelectCombobox(): Locator {
    return this.page.getByRole('combobox').filter({ hasText: /choose the ranch for this guide|choose ranch/i });
  }

  ranchOption(ranchName: string): Locator {
    return this.page.getByRole('option', { name: ranchName });
  }

  // Step 2 — Basic Details
  get firstNameInput(): Locator {
    return this.page.locator('#firstName');
  }

  get lastNameInput(): Locator {
    return this.page.locator('#lastName');
  }

  get emailInput(): Locator {
    return this.page.locator('#email');
  }

  get countrySelectorButton(): Locator {
    return this.page.getByRole('combobox', { name: /country selector/i });
  }

  get phoneInput(): Locator {
    return this.page.locator('input[type="tel"]');
  }

  get dateOfBirthButton(): Locator {
    return this.page.getByRole('button', { name: /select date of birth|^[a-z]{3} \d{2}, \d{4}$/i });
  }

  // Step 3 — Employment Information
  get startDateButton(): Locator {
    return this.page.getByText('Start Date').locator('xpath=following::button[1]');
  }

  get employmentTypeRadioGroup(): Locator {
    return this.page.getByRole('radiogroup').filter({ hasText: /full-time/i });
  }

  employmentTypeOption(type: 'Full-time' | 'Part-time' | 'Contract'): Locator {
    return this.employmentTypeRadioGroup.getByRole('radio', { name: type });
  }

  get yearsExperienceInput(): Locator {
    return this.page.locator('#yearsExperience');
  }

  get experienceLevelAutoCalculatedText(): Locator {
    // Read-only, derived — NOT a selectable dropdown. See docs/dom-snapshots/staff.json.
    return this.page.getByText(/experience level/i).locator('xpath=following::*[1]');
  }

  // Wizard navigation / submission
  get wizardNextButton(): Locator {
    return this.page.getByRole('button', { name: /^next$/i });
  }

  get wizardBackButton(): Locator {
    return this.page.getByRole('button', { name: /^back$/i });
  }

  // UNVERIFIED (see docs/dom-snapshots/staff.json "stepsBeyond3") — best-effort, self-healing.
  get wizardSaveButton(): Locator {
    return this.page.getByRole('button', { name: /^save$|^create guide$|^submit$/i });
  }

  get resendInvitationButton(): Locator {
    return this.page.getByRole('button', { name: /resend invitation|send password setup email/i });
  }

  // ==================== Validations ====================

  async isGuideListLoaded(): Promise<boolean> {
    return this.addGuideButton.isVisible();
  }

  async assertGuideRowVisible(nameOrEmail: string): Promise<void> {
    await expect(this.guideRow(nameOrEmail)).toBeVisible();
  }

  async assertGuideRowNotVisible(nameOrEmail: string): Promise<void> {
    await expect(this.guideRow(nameOrEmail)).toHaveCount(0);
  }

  async assertGuideStatus(nameOrEmail: string, expectedStatus: string): Promise<void> {
    await expect(this.guideRow(nameOrEmail)).toContainText(expectedStatus);
  }

  async assertFieldValidationError(fieldLabel: string): Promise<void> {
    await expect(this.fieldValidationError(fieldLabel)).toBeVisible();
  }

  async assertSuccessToastVisible(): Promise<void> {
    await expect(this.successToast).toBeVisible();
  }

  async assertEmptyStateVisible(): Promise<void> {
    await expect(this.emptyStateMessage).toBeVisible();
  }

  async assertEmploymentTypeOptionsVisible(): Promise<void> {
    await expect(this.employmentTypeOption('Full-time')).toBeVisible();
    await expect(this.employmentTypeOption('Part-time')).toBeVisible();
    await expect(this.employmentTypeOption('Contract')).toBeVisible();
  }

  async assertMandatoryIndicatorVisible(labelText: string): Promise<void> {
    const label = this.page.getByText(new RegExp(`^${labelText}`, 'i')).first();
    await expect(label).toContainText('*');
  }

  async assertControlNotRendered(locator: Locator): Promise<void> {
    await expect(locator).toHaveCount(0);
  }

  // ==================== Actions ====================

  async navigateToStaffGuideList(): Promise<void> {
    await this.withHeal(this.staffGuidesNavLink, (l) => l.click(), 'Staff & Guides Nav Link');
    await this.waitForLoadingToComplete();
  }

  async searchGuides(query: string): Promise<void> {
    await this.withHeal(this.searchInput, (l) => l.fill(query), 'Guide Search Input');
  }

  async toggleCardView(): Promise<void> {
    await this.withHeal(this.cardViewToggle, (l) => l.click(), 'Card View Toggle');
  }

  async toggleTableView(): Promise<void> {
    await this.withHeal(this.tableViewToggle, (l) => l.click(), 'Table View Toggle');
  }

  async openAddGuideForm(): Promise<void> {
    await this.logInfo('Opening Add Guide wizard');
    await this.withHeal(this.addGuideButton, (l) => l.click(), 'Add Guide Button');
  }

  async selectRanchForNewGuide(ranchName: string): Promise<void> {
    await this.withHeal(this.ranchSelectCombobox, (l) => l.click(), 'Ranch Select Combobox');
    await this.withHeal(this.ranchOption(ranchName), (l) => l.click(), `Ranch Option: ${ranchName}`);
  }

  async fillBasicDetails(firstName: string, lastName: string, email: string, phoneDigits: string): Promise<void> {
    if (firstName) await this.withHeal(this.firstNameInput, (l) => l.fill(firstName), 'First Name Input');
    if (lastName) await this.withHeal(this.lastNameInput, (l) => l.fill(lastName), 'Last Name Input');
    if (email) await this.withHeal(this.emailInput, (l) => l.fill(email), 'Email Input');
    if (phoneDigits) await this.withHeal(this.phoneInput, (l) => l.fill(phoneDigits), 'Phone Input');
  }

  async selectDateOfBirth(): Promise<void> {
    await this.withHeal(this.dateOfBirthButton, (l) => l.click(), 'Date of Birth Button');
    const dayCell = this.page.locator('[role="gridcell"] button, table button').first();
    await this.withHeal(dayCell, (l) => l.click(), 'Date of Birth Calendar Day');
  }

  async clickWizardNext(): Promise<void> {
    await this.withHeal(this.wizardNextButton, (l) => l.click(), 'Wizard Next Button');
  }

  async clickWizardBack(): Promise<void> {
    await this.withHeal(this.wizardBackButton, (l) => l.click(), 'Wizard Back Button');
  }

  async selectEmploymentType(type: 'Full-time' | 'Part-time' | 'Contract'): Promise<void> {
    await this.withHeal(this.employmentTypeOption(type), (l) => l.click(), `Employment Type: ${type}`);
  }

  async fillYearsExperience(years: string): Promise<void> {
    await this.withHeal(this.yearsExperienceInput, (l) => l.fill(years), 'Years of Guiding Experience Input');
  }

  async submitGuideForm(): Promise<void> {
    await this.logInfo('Submitting Guide form');
    await this.withHeal(this.wizardSaveButton, (l) => l.click(), 'Guide Save/Submit Button');
    await this.logSuccess('Guide form submitted');
  }

  /**
   * End-to-end convenience: progresses through every confirmed wizard step with the
   * supplied data, leaving any field blank when its value is an empty string so negative
   * (missing-mandatory-field) scenarios can reuse this single method.
   */
  async createGuide(data: {
    ranchName?: string;
    firstName?: string;
    lastName?: string;
    email?: string;
    phoneDigits?: string;
    skipDateOfBirth?: boolean;
    employmentType?: 'Full-time' | 'Part-time' | 'Contract';
    yearsExperience?: string;
  }): Promise<void> {
    await this.openAddGuideForm();
    if (data.ranchName) await this.selectRanchForNewGuide(data.ranchName);
    await this.clickWizardNext();
    await this.fillBasicDetails(data.firstName ?? '', data.lastName ?? '', data.email ?? '', data.phoneDigits ?? '');
    if (!data.skipDateOfBirth) await this.selectDateOfBirth();
    await this.clickWizardNext();
    if (data.employmentType) await this.selectEmploymentType(data.employmentType);
    if (data.yearsExperience) await this.fillYearsExperience(data.yearsExperience);
    await this.clickWizardNext();
    await this.submitGuideForm();
  }

  async openEditGuideForm(nameOrEmail: string): Promise<void> {
    await this.withHeal(this.moreOptionsButton(nameOrEmail), (l) => l.click(), `More Options: ${nameOrEmail}`);
    await this.withHeal(this.editMenuItem, (l) => l.click(), 'Edit Menu Item');
    await this.waitForLoadingToComplete();
  }

  async openChangeStatusMenu(nameOrEmail: string): Promise<void> {
    await this.withHeal(this.moreOptionsButton(nameOrEmail), (l) => l.click(), `More Options: ${nameOrEmail}`);
    await this.withHeal(this.changeStatusMenuItem, (l) => l.click(), 'Change Status Menu Item');
  }

  async selectStatusOption(status: 'Active' | 'On Leave'): Promise<void> {
    const option = this.page.getByRole('option', { name: status }).or(this.page.getByRole('menuitem', { name: status }));
    await this.withHeal(option, (l) => l.click(), `Status Option: ${status}`);
  }

  async clickResendInvitation(): Promise<void> {
    await this.withHeal(this.resendInvitationButton, (l) => l.click(), 'Resend Invitation Button');
  }

  async goToPage(pageNumber: string): Promise<void> {
    await this.withHeal(this.pageNumberButton(pageNumber), (l) => l.click(), `Pagination Page ${pageNumber}`);
  }

  async goToNextPage(): Promise<void> {
    await this.withHeal(this.nextPageButton, (l) => l.click(), 'Pagination Next');
  }

  async goToPreviousPage(): Promise<void> {
    await this.withHeal(this.previousPageButton, (l) => l.click(), 'Pagination Previous');
  }

  async simulateCreateGuideNetworkFailure(): Promise<void> {
    await this.page.route('**/staff/**', (route) => route.abort('failed'));
  }
}
